def sum_of_digits(numbers):
    def sum_digits(num):
        # Convert the number to a positive integer and calculate the sum of its digits
        num = abs(num)
        return sum(int(digit) for digit in str(num))

    def process_list(nested_list):
        total_sum = 0
        for item in nested_list:
            if isinstance(item, list):
                total_sum += process_list(item)
            elif isinstance(item, int):
                total_sum += sum_digits(item)
        return total_sum

    return process_list(numbers)

